def get_all_title_pairs():
    """Returns a list of all available title pair keys."""
    return list(TITLE_PAIRS.keys())

def get_title_pair(key):
    """Returns the title pair configuration for a given key."""
    if key not in TITLE_PAIRS:
        raise ValueError(f"Title pair '{key}' not found. Available pairs: {', '.join(get_all_title_pairs())}")
    return TITLE_PAIRS[key]